   250→// ValidatorActivationChurnLimitDeneb returns the maximum number of validators that can be activated in a slot post Deneb.
   251→func ValidatorActivationChurnLimitDeneb(activeValidatorCount uint64) uint64 {
   252→	limit := calculateChurnLimit(activeValidatorCount)
   253→	// New in Deneb.
   254→	if limit > params.BeaconConfig().MaxPerEpochActivationChurnLimit {
   255→		return params.BeaconConfig().MaxPerEpochActivationChurnLimit
   256→	}
   257→	return limit
   258→}
